<?php $route=$isAtlas?'/atlas':'/organizations';$layerLabels=['experiences'=>'تجربه‌ها','organizations'=>'مجموعه‌ها','mentors'=>'مرشدها']; ?>
<header class="atlas-heading"><span class="eyebrow"><?= $this->icon('pin') ?>از تجربه به گفت‌وگو</span><h1><?= $isAtlas?'اطلس مرشد':'مجموعه‌های تجربه' ?></h1><p class="muted">مسیرهای واقعی را کشف کن؛ مرشدِ آشنا با مسئله‌ات را پیدا کن.</p></header>
<div class="atlas-layout"><aside class="card atlas-filters"><h2>چه مسیری را جست‌وجو می‌کنی؟</h2><details data-filter-panel open><summary class="atlas-filter-toggle">جست‌وجو و فیلترها</summary><form method="get" action="<?= $this->h($this->url($route)) ?>" data-atlas-filters data-places-url="<?= $this->h($this->url('/api/v1/places')) ?>">
<?php if(!($this->config['pretty_urls']??false)): ?><input type="hidden" name="r" value="<?= $route ?>"><?php endif; ?>
<?php foreach(['mentor_id'] as $contextKey):if(!empty($filters[$contextKey])): ?><input type="hidden" name="<?= $contextKey ?>" value="<?= $this->h($filters[$contextKey]) ?>"><?php endif;endforeach; ?><?php if($isAtlas): ?><label>لایهٔ نقشه<select name="layer"><?php foreach($layerLabels as $key=>$label): ?><option value="<?= $key ?>" <?= $layer===$key?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><?php endif; ?>
<label>جست‌وجو<input name="q" maxlength="160" value="<?= $this->h($filters['q']??'') ?>" placeholder="تجربه، مسئله یا مجموعه"></label>
<label>استان<select name="province" data-province><option value="">همهٔ ایران</option><?php foreach($provinces as $p): ?><option value="<?= $this->h($p['id']) ?>" <?= $province===$p['id']?'selected':'' ?>><?= $this->h($p['name']) ?></option><?php endforeach; ?></select></label>
<label>شهرستان<select name="county" data-county><option value="">همهٔ شهرستان‌ها</option><?php foreach($counties as $c): ?><option value="<?= $this->h($c['id']) ?>" <?= $county===$c['id']?'selected':'' ?>><?= $this->h($c['name']) ?></option><?php endforeach; ?></select></label>
<?php require __DIR__.'/classification-filters.php'; ?>
<button>پیدا کن <?= $this->icon('arrow') ?></button><a class="textlink" href="<?= $this->h($this->url($route)) ?>">پاک‌کردن فیلترها</a></form></details></aside>
<div class="atlas-main"><?php if($isAtlas): ?><section class="card atlas-map-card"><div class="section-head"><h2><?= $province?'شهرستان‌های استان انتخاب‌شده':'ایران، از نگاه تجربه‌ها' ?></h2><span><?= $this->number($total) ?> <?= $layerLabels[$layer] ?></span></div><p class="small muted">استان‌ها و شهرستان‌های بدون تجربه نیز قابل انتخاب‌اند. شمارش بر اساس رکوردهای یکتا و مکان تأییدشده است.</p><div class="atlas-map" data-atlas-map data-province="<?= $this->h($province??'') ?>" data-regions="<?= $this->h(json_encode($regions,JSON_THROW_ON_ERROR)) ?>"><p data-map-status role="status">در حال بارگیری نقشه…</p><svg role="group" aria-label="نقشهٔ انتخاب مکان" hidden></svg><button type="button" class="secondary" data-map-retry hidden>تلاش دوباره برای بارگیری نقشه</button></div><p class="small muted">دادهٔ مرجع، بدون ادعای مرزبندی رسمی · <a href="https://www.openstreetmap.org/copyright" rel="noopener">© OpenStreetMap contributors</a></p><p class="small muted">انتخاب استان و شهرستان از فرم بالا هم امکان‌پذیر است؛ موقعیت مکانی دستگاه دریافت نمی‌شود.</p></section><?php endif; ?>
<div class="atlas-summary row section"><?php foreach(['experiences'=>'تجربه','mentors'=>'مرشد','organizations'=>'مجموعه'] as $key=>$label): if(isset($relatedLayers)&&empty($summary[$key])){continue;} ?><span class="tag"><?= $this->number($summary[$key]??0) ?> <?= $label ?></span><?php endforeach; ?></div><?php if(!isset($relatedLayers)): ?><section class="section"><div class="section-head"><h2><?= $layerLabels[$layer] ?> مرتبط</h2><span class="tag"><?= $this->number($total) ?> نتیجه</span></div><div class="atlas-results"><?php foreach($rows as $row):require __DIR__.'/atlas-result.php';endforeach; ?></div><?php if(!$rows): ?><div class="card empty"><h3>هنوز تجربهٔ تأییدشده‌ای برای این انتخاب نداریم</h3><p>مکان یا فیلترها را تغییر بده. تجربه‌های بدون مکان همچنان در بانک تجربه‌ها در دسترس‌اند.</p><a href="<?= $this->h($this->url('/experiences')) ?>">دیدن بانک تجربه‌ها</a></div><?php endif; ?>
<?php if(!empty($unlocated)): ?><section class="section"><h2><?= $layer==='mentors'?'مرشدهای دارای تجربه':'تجربه‌های منتشرشده' ?>، بدون مکان تأییدشده</h2><p class="small muted">این موارد قابل مطالعه و پیگیری‌اند؛ پس از ثبت و تأیید محل تجربه توسط مدیر، روی نقشه هم دیده می‌شوند.</p><div class="atlas-results"><?php foreach($unlocated as $row){require __DIR__.'/atlas-result.php';} ?></div></section><?php endif; ?><nav class="row section" aria-label="صفحه‌بندی نتایج"><?php $query=$filters;unset($query['r']);if($page>1):$query['page']=$page-1; ?><a class="secondary" href="<?= $this->h($this->url($route.'?'.http_build_query($query))) ?>">قبلی</a><?php endif; ?><span>صفحه <?= $this->number($page) ?></span><?php if($page*20<$total):$query['page']=$page+1; ?><a class="secondary" href="<?= $this->h($this->url($route.'?'.http_build_query($query))) ?>">بعدی</a><?php endif; ?></nav></section><?php else: ?><?php foreach($relatedLayers as $relatedLayer=>$relatedData): if(!$relatedData['rows']){continue;} ?><section class="section atlas-related-group"><div class="section-head"><h2><?= $layerLabels[$relatedLayer] ?> مرتبط</h2><span class="tag"><?= $this->number($relatedData['total']) ?></span></div><div class="atlas-results"><?php $layer=$relatedLayer;foreach($relatedData['rows'] as $row){require __DIR__.'/atlas-result.php';} ?></div><?php if($relatedData['total']>20): ?><a class="textlink" href="<?= $this->h($this->url('/atlas?'.http_build_query(array_replace($filters,['layer'=>$relatedLayer,'page'=>1,'only_layer'=>1])))) ?>">نتایج بیشتر</a><?php endif; ?></section><?php endforeach; ?><?php endif; ?></div></div>
